--
-- Name: v_bursa_player_scouting; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bursa_player_scouting AS
 WITH market AS (
         SELECT transactions.player_id,
            count(*) AS trade_volume,
            round(avg(transactions.transaction_price), 2) AS avg_tx_price
           FROM public.transactions
          GROUP BY transactions.player_id
        ), real_stats AS (
         SELECT pms.playerid,
            count(*) AS matches_played,
            sum(pms.goals) AS total_goals,
            sum(pms.assists) AS total_assists,
            sum(pms.tackles) AS total_tackles
           FROM public.playermatchstats pms
          GROUP BY pms.playerid
        )
 SELECT b.player_id,
    (((b.first_name)::text || ' '::text) || (b.last_name)::text) AS bursa_name,
    b."position",
    b.current_price,
    COALESCE(mk.trade_volume, (0)::bigint) AS trade_volume,
    COALESCE(mk.avg_tx_price, (0)::numeric) AS avg_tx_price,
    COALESCE(rs.matches_played, (0)::bigint) AS matches_played,
    COALESCE(rs.total_goals, (0)::bigint) AS total_goals,
    COALESCE(rs.total_assists, (0)::bigint) AS total_assists,
    COALESCE(rs.total_tackles, (0)::bigint) AS total_tackles
   FROM (((public.players b
     JOIN public.player_mapping m ON ((m.bursa_player_id = b.player_id)))
     LEFT JOIN market mk ON ((mk.player_id = b.player_id)))
     LEFT JOIN real_stats rs ON ((rs.playerid = m.real_player_id)));


--
-- Name: v_real_player_market_value; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_real_player_market_value AS
 WITH price_range AS (
         SELECT price_history.player_id,
            min(price_history.recorded_price) AS min_price,
            max(price_history.recorded_price) AS max_price
           FROM public.price_history
          GROUP BY price_history.player_id
        )
 SELECT r.playerid,
    r.playername,
    r."position",
    r.nativecountry,
    t.teamname,
    pf.salary,
    b.current_price AS bursa_current_price,
    COALESCE(pr.min_price, 0) AS bursa_min_price,
    COALESCE(pr.max_price, 0) AS bursa_max_price
   FROM (((((public.player r
     JOIN public.playsfor_player pf ON ((pf.playerid = r.playerid)))
     JOIN public.team t ON ((t.teamid = pf.teamid)))
     JOIN public.player_mapping m ON ((m.real_player_id = r.playerid)))
     JOIN public.players b ON ((b.player_id = m.bursa_player_id)))
     LEFT JOIN price_range pr ON ((pr.player_id = m.bursa_player_id)));


